import re, os, sys

if not os.path.exists('/tmp/crypto-article-raw.md'):
    print('ARTICLE_INVALID: /tmp/crypto-article-raw.md was not created'); sys.exit(1)

with open('/tmp/crypto-article-raw.md', 'r', encoding='utf-8', errors='ignore') as f:
    content = f.read()

content = re.sub(r'\x1b\[[0-9;]*[mGKHFA-Za-z]', '', content)
content = re.sub(r'<thinking>.*?</thinking>', '', content, flags=re.DOTALL|re.IGNORECASE)
for pat in [r'^Waiting for agent reply.*$', r'^Sending message.*$', r'^\s*[⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏].*$']:
    content = re.sub(pat, '', content, flags=re.MULTILINE)
content = re.sub(r'\n{3,}', '\n\n', content).strip()

with open('/tmp/crypto-article.md', 'w', encoding='utf-8') as f:
    f.write(content + '\n')
print('[CLEAN] Article sanitized.')
PYEOF
